from ortools.sat.python import cp_model
import itertools
import json

def main():
    W = 10
    H = 10

    T = [1, 2, 3, 4, 5, 6, 7]

    length = {1: 5, 2: 3, 3: 4, 4: 2, 5: 3, 6: 4, 7: 4}
    width = {1: 2, 2: 3, 3: 4, 4: 2, 5: 2, 6: 1, 7: 3}

    min_qty = {1: 1, 2: 0, 3: 0, 4: 1, 5: 0, 6: 0, 7: 0}
    max_qty = {1: 2, 2: 2, 3: 1, 4: 4, 5: 2, 6: 1, 7: 1}

    utility = {1: 28, 2: 40, 3: 63, 4: 13, 5: 31, 6: 10, 7: 44}

    model = cp_model.CpModel()

    place = {}
    x = {}
    y = {}
    rot = {}

    for t in T:
        place[t] = []
        x[t] = []
        y[t] = []
        rot[t] = []

        for i in range(max_qty[t]):
            place_var = model.NewBoolVar(f"place_{t}_{i}")
            x_var = model.NewIntVar(0, W, f"x_{t}_{i}")
            y_var = model.NewIntVar(0, H, f"y_{t}_{i}")
            rot_var = model.NewBoolVar(f"rot_{t}_{i}")

            place[t].append(place_var)
            x[t].append(x_var)
            y[t].append(y_var)
            rot[t].append(rot_var)

    for t in T:
        placed_sum = sum(place[t][i] for i in range(max_qty[t]))
        model.Add(placed_sum >= min_qty[t])
        model.Add(placed_sum <= max_qty[t])

    w_var = {}
    h_var = {}

    for t in T:
        w_var[t] = []
        h_var[t] = []
        for i in range(max_qty[t]):
            w = model.NewIntVar(0, max(length[t], width[t]), f"w_{t}_{i}")
            model.Add(w == length[t]).OnlyEnforceIf(rot[t][i].Not())
            model.Add(w == width[t]).OnlyEnforceIf(rot[t][i])

            h = model.NewIntVar(0, max(length[t], width[t]), f"h_{t}_{i}")
            model.Add(h == width[t]).OnlyEnforceIf(rot[t][i].Not())
            model.Add(h == length[t]).OnlyEnforceIf(rot[t][i])

            w_var[t].append(w)
            h_var[t].append(h)

    for t in T:
        for i in range(max_qty[t]):
            model.Add(x[t][i] + w_var[t][i] <= W).OnlyEnforceIf(place[t][i])
            model.Add(y[t][i] + h_var[t][i] <= H).OnlyEnforceIf(place[t][i])

    all_boxes = []
    for t in T:
        for i in range(max_qty[t]):
            all_boxes.append((t, i))

    for idx1, (t1, i1) in enumerate(all_boxes):
        for idx2, (t2, i2) in enumerate(all_boxes):
            if idx1 >= idx2:
                continue

            left = model.NewBoolVar(f"left_{t1}_{i1}_{t2}_{i2}")
            right = model.NewBoolVar(f"right_{t1}_{i1}_{t2}_{i2}")
            below = model.NewBoolVar(f"below_{t1}_{i1}_{t2}_{i2}")
            above = model.NewBoolVar(f"above_{t1}_{i1}_{t2}_{i2}")

            model.Add(x[t1][i1] + w_var[t1][i1] <= x[t2][i2]).OnlyEnforceIf(left)
            model.Add(x[t2][i2] + w_var[t2][i2] <= x[t1][i1]).OnlyEnforceIf(right)
            model.Add(y[t1][i1] + h_var[t1][i1] <= y[t2][i2]).OnlyEnforceIf(below)
            model.Add(y[t2][i2] + h_var[t2][i2] <= y[t1][i1]).OnlyEnforceIf(above)

            model.AddBoolOr([
                place[t1][i1].Not(),
                place[t2][i2].Not(),
                left, right, below, above
            ])

    objective_terms = []
    for t in T:
        for i in range(max_qty[t]):
            objective_terms.append(place[t][i] * utility[t])

    model.Maximize(sum(objective_terms))

    solver = cp_model.CpSolver()
    solver.parameters.max_time_in_seconds = 30.0
    solver.parameters.num_search_workers = 8

    status = solver.Solve(model)

    if status in (cp_model.OPTIMAL, cp_model.FEASIBLE):
        total_utility_value = 0
        box_placements = []

        for t in T:
            for i in range(max_qty[t]):
                if solver.Value(place[t][i]):
                    x_val = solver.Value(x[t][i])
                    y_val = solver.Value(y[t][i])
                    rot_val = solver.Value(rot[t][i])
                    total_utility_value += utility[t]
                    box_placements.append([t, x_val, y_val, rot_val])

        print(json.dumps({
            "total_utility_value": total_utility_value,
            "box_placements": box_placements
        }, separators=(',', ':')))
    else:
        print(json.dumps({
            "total_utility_value": 0,
            "box_placements": []
        }, separators=(',', ':')))

if __name__ == "__main__":
    main()
